     1	import React from 'react';
     2	import { describe, test, expect, vi } from 'vitest';
     3	import { render, screen } from '@testing-library/react';
     4	import { FooterNavColumn, hasIntentionalLineBreak } from './index';
     5	import type { FooterNavGroupEntry, LinkEntry } from 'app/types/contentful';
     6	
     7	// ZimmIcon pulls in the base SFCC icons barrel (app/components/icons), which has a top-level
     8	// side effect (AmexSymbol.viewBox = ...) that throws under Vitest — SVG imports resolve to raw
     9	// path strings here, not components. No test in this repo has rendered an icon-consuming
    10	// component before, so this gap was never caught; fixing the SVG transform lives in
    11	// vitest.config.ts, Tier 1 test config this task cannot touch. Mocking the smallest surface
    12	// (ZimmIcon itself) routes around it without losing anything this test actually asserts on —
    13	// the aria-label/href under test come from ZimmContactIconRow's own wrapper, not from ZimmIcon.
    14	vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
    15	  // Forwards aria-label/aria-hidden — ZimmContactIconRow's fallback (no-href) branch puts the
    16	  // accessible name on ZimmIcon itself, not on its wrapper, so a no-op stub would silently drop
    17	  // the exact a11y contract this test suite asserts on.
    18	  ZimmIcon: (props: { 'aria-label'?: string; 'aria-hidden'?: boolean }) => (
    19	    <span aria-label={props['aria-label']} aria-hidden={props['aria-hidden']} />
    20	  ),
    21	}));
    22	
    23	const makeLink = (id: string, label: string, href = '#'): LinkEntry => ({
    24	  sys: { id, contentType: { sys: { id: 'link' } } },
    25	  fields: { label, href },
    26	});
    27	
    28	const makeGroup = (overrides: Partial<FooterNavGroupEntry['fields']> = {}): FooterNavGroupEntry => ({
    29	  sys: { id: 'group-test', contentType: { sys: { id: 'footerNavGroup' } } },
    30	  fields: {
    31	    heading: 'About',
    32	    links: [makeLink('link-1', 'Our Story'), makeLink('link-2', 'Careers')],
    33	    ...overrides,
    34	  },
    35	});
    36	
    37	describe('hasIntentionalLineBreak', () => {
    38	  test('true for a label carrying a non-breaking space', () => {
    39	    expect(hasIntentionalLineBreak('Acknowledgement of Country')).toBe(true);
    40	  });
    41	
    42	  test('false for an ordinary single-line label', () => {
    43	    expect(hasIntentionalLineBreak('Book an Appointment')).toBe(false);
    44	  });
    45	
    46	  test('false for an empty label', () => {
    47	    expect(hasIntentionalLineBreak('')).toBe(false);
    48	  });
    49	});
    50	
    51	describe('FooterNavColumn', () => {
    52	  test('renders the heading and every link as an accessible link', () => {
    53	    render(<FooterNavColumn group={makeGroup()} />);
    54	
    55	    expect(screen.getByText('About')).toBeInTheDocument();
    56	    expect(screen.getByRole('link', { name: 'Our Story' })).toHaveAttribute('href', '#');
    57	    expect(screen.getByRole('link', { name: 'Careers' })).toHaveAttribute('href', '#');
    58	  });
    59	
    60	  test('omits the contact-channel row when showContactChannels is not set', () => {
    61	    render(<FooterNavColumn group={makeGroup()} />);
    62	
    63	    expect(screen.queryByLabelText(/call us/i)).not.toBeInTheDocument();
    64	    expect(screen.queryByLabelText(/whatsapp/i)).not.toBeInTheDocument();
    65	    expect(screen.queryByLabelText(/email us/i)).not.toBeInTheDocument();
    66	  });
    67	
    68	  test('renders the contact-channel row when showContactChannels is true', () => {
    69	    render(
    70	      <FooterNavColumn
    71	        group={makeGroup({ heading: 'Contact', showContactChannels: true })}
    72	        phoneHref="tel:+61280808080"
    73	        whatsAppHref="https://wa.me/61280808080"
    74	        emailHref="mailto:care@zimmermann.com"
    75	      />,
    76	    );
    77	
    78	    expect(screen.getByRole('link', { name: 'Call us' })).toHaveAttribute('href', 'tel:+61280808080');
    79	    expect(screen.getByRole('link', { name: /whatsapp/i })).toHaveAttribute('href', 'https://wa.me/61280808080');
    80	    expect(screen.getByRole('link', { name: 'Email us' })).toHaveAttribute('href', 'mailto:care@zimmermann.com');
    81	  });
    82	
    83	  test('renders a non-interactive fallback for a contact channel with no href, not a dead link', () => {
    84	    render(<FooterNavColumn group={makeGroup({ showContactChannels: true })} />);
    85	
    86	    expect(screen.queryByRole('link', { name: 'Call us' })).not.toBeInTheDocument();
    87	    expect(screen.getByLabelText('Call us')).toBeInTheDocument();
    88	  });
    89	});

