150	    mockHook({ modalOpen: true, handleModalSubmit });
151	    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);
152	
153	    await userEvent.click(screen.getByRole('button', { name: 'mock-continue' }));
154	
155	    expect(handleModalSubmit).toHaveBeenCalledWith('Jane', 'Smith');
156	  });
157	
158	  test('uses the CMS-sourced email label and subscribe button text when useUiCopy resolves them', () => {
159	    mockUseUiCopy.mockReturnValue({
160	      t: (key: string, fallback: string) => {
161	        if (key === 'footer.subscribe.emailLabel') return 'E-mail';
162	        if (key === 'footer.subscribe.buttonLabel') return 'S’inscrire';
163	        return fallback;
164	      },
165	      isLoading: false,
166	    });
167	    render(<ZimmSubscribeSection {...baseProps} />);
168	
169	    expect(screen.getByRole('textbox', { name: 'E-mail' })).toBeInTheDocument();
170	    expect(screen.getByRole('button', { name: 'S’inscrire' })).toBeInTheDocument();
171	  });
172	
173	  test('uses the CMS-sourced success and unavailable messages when useUiCopy resolves them', () => {
174	    mockUseUiCopy.mockReturnValue({
175	      t: (key: string, fallback: string) => {
176	        if (key === 'footer.subscribe.successMessage') return 'Merci !';
177	        if (key === 'footer.subscribe.unavailableMessage') return 'Indisponible';
178	        return fallback;
179	      },
180	      isLoading: false,
181	    });
182	
183	    mockHook({ submitState: 'success' });
184	    const { rerender } = render(<ZimmSubscribeSection {...baseProps} />);
185	    expect(screen.getByText('Merci !')).toBeInTheDocument();
186	
187	    mockHook({ submitState: 'unavailable' });
188	    rerender(<ZimmSubscribeSection {...baseProps} />);
189	    expect(screen.getByRole('alert')).toHaveTextContent('Indisponible');
190	  });
191	
192	  test('modal cancel calls closeModal', async () => {
193	    const closeModal = vi.fn();
194	    mockHook({ modalOpen: true, closeModal });
195	    render(<ZimmSubscribeSection {...baseProps} enableNameCapture />);
196	
197	    await userEvent.click(screen.getByRole('button', { name: 'mock-cancel' }));
198	
199	    expect(closeModal).toHaveBeenCalled();
200	  });
201	});

