  1	/**
  2	 * `parseRichText` is the seam between Business-Manager-authored copy and the DOM, so its
  3	 * rejection behaviour is the thing worth pinning down. Every hostile-input case below is a
  4	 * row in one table, asserted against the *rendered* markup rather than the node tree — that
  5	 * is the form an attacker would have to reach, and it is what a reviewer can read at a glance.
  6	 *
  7	 * `renderToStaticMarkup` is deliberate: it proves the output as React actually serialises it,
  8	 * including React's own text escaping, rather than re-implementing that escaping in the test.
  9	 */
 10	import { describe, expect, test } from 'vitest';
 11	import React from 'react';
 12	import { renderToStaticMarkup } from 'react-dom/server';
 13	import { decodeEntities, isBlankRichText, parseRichText, richTextToPlainText } from './richText';
 14	
 15	const render = (input?: string | null) => renderToStaticMarkup(<>{parseRichText(input)}</>);
 16	
 17	describe('parseRichText — rejection matrix', () => {
 18	  // Each row: what an attacker or a bad CMS paste could put in the field, and what must
 19	  // survive. `mustNotContain` is checked against the serialised markup.
 20	  test.each`
 21	    name                           | input                                                  | mustNotContain    | mustContain
 22	    ${'script element'}            | ${'<p>hi</p><script>alert(1)</script>'}                | ${'<script'}      | ${'<p>hi</p>'}
 23	    ${'script body is not text'}   | ${'<script>stealCookies()</script>'}                   | ${'stealCookies'} | ${''}
 24	    ${'uppercase SCRIPT'}          | ${'<SCRIPT>alert(1)</SCRIPT>ok'}                       | ${'alert(1)'}     | ${'ok'}
 25	    ${'nested script'}             | ${'<script><script>alert(1)</script></script>safe'}    | ${'alert'}        | ${'safe'}
 26	    ${'inline event handler'}      | ${'<p onclick="evil()">text</p>'}                      | ${'onclick'}      | ${'<p>text</p>'}
 27	    ${'img onerror'}               | ${'<img src=x onerror=alert(1)>caption'}               | ${'onerror'}      | ${'caption'}
 28	    ${'javascript: href'}          | ${'<a href="javascript:alert(1)">link</a>'}            | ${'javascript:'}  | ${'link'}
 29	    ${'data: href'}                | ${'<a href="data:text/html,<script>x</script>">l</a>'} | ${'data:'}        | ${'l'}
 30	    ${'iframe'}                    | ${'<iframe src="https://evil.test"></iframe>after'}    | ${'<iframe'}      | ${'after'}
 31	    ${'svg onload'}                | ${'<svg onload=alert(1)></svg>tail'}                   | ${'onload'}       | ${'tail'}
 32	    ${'style block'}               | ${'<style>body{display:none}</style>copy'}             | ${'display:none'} | ${'copy'}
 33	    ${'form and input'}            | ${'<form><input value="x"></form>body'}                | ${'<input'}       | ${'body'}
 34	    ${'object embed'}              | ${'<object data="x"></object><embed src="y">z'}        | ${'<object'}      | ${'z'}
 35	    ${'class attribute stripped'}  | ${'<p class="leak">t</p>'}                             | ${'class'}        | ${'<p>t</p>'}
 36	    ${'style attribute stripped'}  | ${'<p style="position:fixed">t</p>'}                   | ${'style'}        | ${'<p>t</p>'}
 37	    ${'id attribute stripped'}     | ${'<li id="x">t</li>'}                                 | ${'id='}          | ${'<li>t</li>'}
 38	    ${'encoded script stays text'} | ${'&lt;script&gt;alert(1)&lt;/script&gt;'}             | ${'<script'}      | ${'&lt;script&gt;'}
 39	    ${'attr value containing gt'}  | ${'<a title="a > b">shown</a>'}                        | ${'title'}        | ${'shown'}
 40	    ${'unknown tag is unwrapped'}  | ${'<div><span>kept</span></div>'}                      | ${'<div'}         | ${'kept'}
 41	    ${'comment-ish input'}         | ${'<!-- <script>x</script> -->visible'}                | ${'<script'}      | ${'visible'}
 42	  `('$name', ({ input, mustNotContain, mustContain }) => {
 43	    const markup = render(input as string);
 44	    if (mustNotContain) expect(markup).not.toContain(mustNotContain as string);
 45	    if (mustContain) expect(markup).toContain(mustContain as string);
 46	  });
 47	
