    10	
    11	type ZimmProductStyleCodeProps = {
    12	  /**
    13	   * The master product's style number. This is the style code shown to shoppers, which is not
    14	   * the same value as the variant `product.id`.
    15	   */
    16	  value?: string;
    17	};
