    19	/**
    20	 * Atom — the "Style Code: 7300JS261" line. Renders nothing when no style code is available.
    21	 *
    22	 * The label is the hardcoded LABEL constant above rather than CMS microcopy: useContentful.ts
    23	 * requests entries with no `locale` parameter, so a `uiCopy` lookup would serve the space
    24	 * default to all eight storefronts regardless of site. zimmSubscribeModal/index.tsx hardcodes
    25	 * its copy the same way.
    26	 */
    27	export const ZimmProductStyleCode = ({ value }: ZimmProductStyleCodeProps) => {
    28	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_STYLE_CODE_RECIPE, {});
    29	  if (!value) return null;
    30	
    31	  return (
    32	    <chakra.div __css={styles.root} textStyle="caption" data-testid="product-style-code">
